import React from 'react';

import { omitTransientProps } from 'utils/emotion';

import {
  StyledErrorIcon,
  StyledErrorMessage,
  StyledGroup,
} from '../Radio.styles';
import type { RadioRootProps } from '../Radio.types';

export const RadioRoot = React.forwardRef<
  React.ElementRef<typeof StyledGroup>,
  RadioRootProps
>(
  (
    { children, error = false, errorMessage, ...props },
    forwardedRef,
  ): JSX.Element => (
    <StyledGroup
      {...omitTransientProps(props)}
      ref={forwardedRef}
      $error={error}
      aria-errormessage={error ? 'radio-error-message' : undefined}
      aria-invalid={error}
    >
      {children}
      {error && errorMessage ? (
        <StyledErrorMessage aria-live="assertive" id="radio-error-message">
          <StyledErrorIcon aria-hidden size="medium" />
          {errorMessage}
        </StyledErrorMessage>
      ) : null}
    </StyledGroup>
  ),
);

RadioRoot.displayName = 'Radio.Root';
